using System.Data;
using Bank.Payments.Domain.Port;
using Bank.Payments.Infrastructure;
using Microsoft.Data.SqlClient;

namespace Bank.Payments.Adapters.Out.Sql;

/// <summary>Adapter of the port DebitGateway over the legacy program db_cuentas..sp_debito.</summary>
public sealed class SqlDebitGateway(Db db) : DebitGateway
{
    private const string Program = "db_cuentas..sp_debito";

    public int DebitAccount(string? accountNumber, string? accountType, decimal? amount, string? reference)
    {
        return Execute(accountNumber, accountType, amount, reference);
    }

    public void DebitCommission(string? accountNumber, string? accountType, decimal? amount, string? reference)
    {
        Execute(accountNumber, accountType, amount, reference);
    }

    private int Execute(string? accountNumber, string? accountType, decimal? amount, string? reference)
    {
        using var command = db.Command(Program);
        command.CommandType = CommandType.StoredProcedure;

        var returnCode = new SqlParameter("@return_code", SqlDbType.Int)
        {
            Direction = ParameterDirection.ReturnValue
        };
        command.Parameters.Add(returnCode);

        command.Parameters.AddWithValue("@i_cuenta", (object?)accountNumber ?? DBNull.Value);
        command.Parameters.AddWithValue("@i_tipo", (object?)accountType ?? DBNull.Value);
        command.Parameters.AddWithValue("@i_valor", (object?)amount ?? DBNull.Value);
